import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

// Corrigir ícones padrão do Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

// Função para calcular distância em km (Haversine)
function calcularDistancia(lat1, lon1, lat2, lon2) {
  const R = 6371; // Raio da Terra em km
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c; // Distância em km
}

function MapView() {
  const [position, setPosition] = useState(null);
  const [revendas, setRevendas] = useState([]);

  useEffect(() => {
    // 👉 1. Obter localização do utilizador
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setPosition([pos.coords.latitude, pos.coords.longitude]);
        },
        (err) => {
          console.error("Erro ao obter localização:", err);
          setPosition([-23.55052, -46.633308]); // fallback São Paulo
        }
      );
    } else {
      alert("Geolocalização não suportada pelo navegador.");
      setPosition([-23.55052, -46.633308]);
    }

    // 👉 2. Buscar revendas do backend
    fetch("http://localhost:5000/api/revendas")
      .then((res) => res.json())
      .then((data) => {
        setRevendas(data);
      })
      .catch((err) => console.error("Erro ao buscar revendas:", err));
  }, []);

  // 👉 3. Filtrar revendas próximas (num raio de 5 km)
  const revendasProximas =
    position && revendas.length > 0
      ? revendas.filter((rev) => {
          const lat = parseFloat(rev.latitude);
          const lng = parseFloat(rev.longitude);
          if (isNaN(lat) || isNaN(lng)) return false;
          const dist = calcularDistancia(position[0], position[1], lat, lng);
          return dist <= 5; // raio de 5 km
        })
      : [];

  return (
    <div style={{ height: "500px", width: "100%" }}>
      {position ? (
        <MapContainer center={position} zoom={14} style={{ height: "100%", width: "100%" }}>
          <TileLayer
            attribution='&copy; OpenStreetMap'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />

          {/* 📍 Localização do utilizador */}
          <Marker position={position}>
            <Popup>📍 Você está aqui</Popup>
          </Marker>

          {/* 🏪 Revendas próximas */}
          {revendasProximas.map((rev, index) => (
            <Marker key={index} position={[parseFloat(rev.latitude), parseFloat(rev.longitude)]}>
              <Popup>
                <strong>{rev["Razão Social"] || rev.nome || "Revenda"}</strong> <br />
                <a
                  href={`https://waze.com/ul?ll=${rev.latitude},${rev.longitude}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Abrir no Waze
                </a>
                <br />
                <a
                  href={`https://www.google.com/maps?q=${rev.latitude},${rev.longitude}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Abrir no Google Maps
                </a>
              </Popup>
            </Marker>
          ))}
        </MapContainer>
      ) : (
        <p>A obter localização...</p>
      )}
    </div>
  );
}

export default MapView;
